import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0]=='n':
        return None
    r = T(int(arr[0]))
    q = deque([r]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def same_brute(p, q):
    if p is None and q is None: return True
    if p is None or q is None: return False
    if p.v != q.v: return False
    return same_brute(p.l, q.l) and same_brute(p.r, q.r)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if len(data) < 2:
        sys.exit(0)
    n = int(data[0])
    p = build(data[1:1+n])
    m = int(data[1+n])
    q = build(data[2+n:2+n+m])
    print('true' if same_brute(p, q) else 'false')

import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

