        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def preorder(node):
    if node is None: return '#'
    return f'{node.v},{preorder(node.l)},{preorder(node.r)}'

def same_best(p, q):
    return preorder(p) == preorder(q)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if len(data) < 2:
        sys.exit(0)
    n = int(data[0])
    p = build(data[1:1+n])
    m = int(data[1+n])
    q = build(data[2+n:2+n+m])
